import React from "react";
import { motion } from "framer-motion";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faDatabase, faChartLine, faCode, faCogs } from '@fortawesome/free-solid-svg-icons';
import '../assets/styles/Expertise.scss';

/**
 * Expertise Component - Enhanced with Scroll Animations
 * 
 * Displays technical expertise across four skill domains with staggered
 * fade-up entrance animations. Professional animation timing maintains
 * credibility for data role portfolios.
 * 
 * Animation Specs:
 * - Fade-up effect: opacity 0→1, translateY 60px→0
 * - Stagger delay: 0.15s between skill cards (4-card grid)
 * - Section header animates first, then cards
 * - Respects prefers-reduced-motion
 */

const labelsFirst = [
    "PySpark",
    "SQL",
    "Databricks",
    "ETL Pipelines",
    "Data Modeling",
    "Delta Lake"
];

const labelsSecond = [
    "Power BI",
    "Tableau",
    "DAX",
    "Data Visualization",
    "Dashboard Development"
];

const labelsThird = [
    "Python",
    "Pandas",
    "NumPy",
    "Git",
    "Power Platform",
    "Excel"
];

const labelsFourth = [
    "Data Quality",
    "Stakeholder Management",
    "Process Automation",
    "Statistical Analysis"
];

interface SkillCardProps {
  icon: any;
  title: string;
  description: string;
  techStack: string[];
  index: number;
}

function Chip(props: { className: string; label: string }) {
    return <span className={props.className}>{props.label}</span>;
}

const SkillCard: React.FC<SkillCardProps> = ({ icon, title, description, techStack, index }) => {
  return (
    <motion.div
      className="skill"
      initial={{ opacity: 0, y: 60 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-80px" }}
      transition={{
        duration: 0.6,
        delay: index * 0.15, // Stagger by 150ms for 4-card grid
        ease: [0.25, 0.46, 0.45, 0.94]
      }}
    >
      <FontAwesomeIcon icon={icon} size="3x"/>
      <h3>{title}</h3>
      <p>{description}</p>
      <div className="flex-chips">
        <span className="chip-title">Tech stack:</span>
        {techStack.map((label: string, idx: number) => (
          <Chip key={idx} className='chip' label={label} />
        ))}
      </div>
    </motion.div>
  );
};

function Expertise() {
    const skills = [
      {
        icon: faDatabase,
        title: "Data Engineering",
        description: "Experienced in designing and building scalable data pipelines and ETL processes. Proficient in implementing medallion architecture patterns and optimizing data workflows for enterprise-scale analytics platforms.",
        techStack: labelsFirst
      },
      {
        icon: faChartLine,
        title: "Business Intelligence",
        description: "Skilled in developing interactive dashboards and reports that drive data-driven decision making. Expertise in translating complex data into actionable insights through compelling visualizations and KPI frameworks.",
        techStack: labelsSecond
      },
      {
        icon: faCode,
        title: "Programming & Analytics",
        description: "Strong programming foundation with focus on data manipulation, statistical analysis, and automation. Proficient in leveraging modern tools and frameworks to deliver efficient, maintainable analytical solutions.",
        techStack: labelsThird
      },
      {
        icon: faCogs,
        title: "Data Governance & Operations",
        description: "Committed to maintaining high data quality standards and implementing robust governance frameworks. Experienced in stakeholder management and driving process improvements through automation and best practices.",
        techStack: labelsFourth
      }
    ];

    return (
        <div className="container section-reveal" id="expertise">
            <div className="skills-container">
                <motion.h1
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true, margin: "-50px" }}
                  transition={{ duration: 0.5 }}
                >
                  Expertise
                </motion.h1>
                <div className="skills-grid">
                    {skills.map((skill, index) => (
                      <SkillCard
                        key={index}
                        icon={skill.icon}
                        title={skill.title}
                        description={skill.description}
                        techStack={skill.techStack}
                        index={index}
                      />
                    ))}
                </div>
            </div>
        </div>
    );
}

export default Expertise;
