import React from 'react';
import { motion, useScroll } from 'framer-motion';
import '../assets/styles/ScrollProgress.scss';

/**
 * ScrollProgress Component
 * 
 * Displays a fixed progress bar at the top of the viewport that fills
 * as the user scrolls through the page. Provides visual feedback on
 * scroll position and content completion.
 * 
 * Features:
 * - Smooth scroll-linked animation
 * - Professional gradient (data/tech aesthetic)
 * - Mobile responsive
 * - Zero performance impact (GPU-accelerated)
 */
const ScrollProgress: React.FC = () => {
  const { scrollYProgress } = useScroll();

  return (
    <motion.div
      className="scroll-progress"
      style={{
        scaleX: scrollYProgress,
      }}
      initial={{ scaleX: 0 }}
      aria-hidden="true" // Decorative element, hide from screen readers
    />
  );
};

export default ScrollProgress;
