import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { HoverBorderGradient } from "./ui/hover-border-gradient";
import { ReactComponent as HomeIconSvg } from "../assets/images/home-svgrepo-com.svg";
import { ReactComponent as ContentIconSvg } from "../assets/images/content-svgrepo-com.svg";

const navItems = [
  ['Expertise', 'expertise'],
  ['History', 'history'],
  ['Projects', 'projects'],
  ['Contact', 'contact']
];

function Navigation() {
  const [menuOpen, setMenuOpen] = useState<boolean>(false);

  const scrollToSection = (section: string) => {
    const element = document.getElementById(section);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
    setMenuOpen(false);
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <nav
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 1000,
        padding: '16px 24px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        pointerEvents: 'none',
      }}
    >
      {/* Home Button with Hover Border Gradient */}
      <div style={{ pointerEvents: 'auto' }}>
        <HoverBorderGradient onClick={scrollToTop} duration={0.8}>
          <HomeIconSvg
            style={{ width: '28px', height: '28px' }}
            className="nav-icon"
          />
        </HoverBorderGradient>
      </div>

      {/* Menu Button with Pop Slider */}
      <div style={{ position: 'relative', pointerEvents: 'auto' }}>
        <HoverBorderGradient onClick={() => setMenuOpen(!menuOpen)} duration={0.8}>
          <ContentIconSvg
            style={{ width: '28px', height: '28px' }}
            className="nav-icon"
          />
        </HoverBorderGradient>

        {/* Pop Slider Menu */}
        <AnimatePresence>
          {menuOpen && (
            <motion.div
              initial={{ opacity: 0, y: -10, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.95 }}
              transition={{ duration: 0.2 }}
              style={{
                position: 'absolute',
                top: 'calc(100% + 12px)',
                right: 0,
                backgroundColor: 'rgba(0, 0, 0, 0.9)',
                backdropFilter: 'blur(10px)',
                borderRadius: '12px',
                padding: '8px',
                minWidth: '160px',
                border: '1px solid rgba(255, 255, 255, 0.1)',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.5)',
              }}
            >
              {navItems.map((item, index) => (
                <motion.button
                  key={item[0]}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ duration: 0.2, delay: index * 0.05 }}
                  onClick={() => scrollToSection(item[1])}
                  style={{
                    display: 'block',
                    width: '100%',
                    padding: '12px 16px',
                    background: 'transparent',
                    border: 'none',
                    color: 'white',
                    fontSize: '0.95rem',
                    fontFamily: "'Geist', 'Lato', sans-serif",
                    textAlign: 'left',
                    cursor: 'pointer',
                    borderRadius: '8px',
                    transition: 'background-color 0.2s ease',
                  }}
                  whileHover={{
                    backgroundColor: 'rgba(255, 255, 255, 0.1)',
                  }}
                  whileTap={{
                    scale: 0.98,
                  }}
                >
                  {item[0]}
                </motion.button>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </nav>
  );
}

export default Navigation;
