import React from "react";
import { motion } from "framer-motion";
import mock01 from '../assets/images/mock01.png';
import mock02 from '../assets/images/mock02.png';
import mock03 from '../assets/images/mock03.png';
import '../assets/styles/Project.scss';

/**
 * Project Component - Enhanced with Scroll Animations
 * 
 * Displays portfolio projects with staggered fade-up entrance animations.
 * Animation triggers when project cards enter viewport, creating a polished
 * and professional presentation suitable for data role portfolios.
 * 
 * Animation Specs:
 * - Fade-up effect: opacity 0→1, translateY 50px→0
 * - Stagger delay: 0.1s between cards
 * - Fires once per session (viewport: { once: true })
 * - Smooth easing: cubic-bezier(0.25, 0.46, 0.45, 0.94)
 */

interface ProjectCardProps {
  title: string;
  description: string;
  image: string;
  link: string;
  index: number;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ title, description, image, link, index }) => {
  return (
    <motion.div
      className="project"
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ 
        once: true, 
        margin: "-100px" // Trigger animation 100px before entering viewport
      }}
      transition={{
        duration: 0.6,
        delay: index * 0.1, // Stagger by 100ms
        ease: [0.25, 0.46, 0.45, 0.94] // Smooth cubic-bezier easing
      }}
    >
      <a href={link} target="_blank" rel="noreferrer">
        <img src={image} className="zoom" alt={title} width="100%" />
      </a>
      <a href={link} target="_blank" rel="noreferrer">
        <h2>{title}</h2>
      </a>
      <p>{description}</p>
    </motion.div>
  );
};

function Project() {
  const projects = [
    {
      title: "Credit Risk Analysis: Loan Default Prediction (EDA)",
      description: "Exploratory data analysis on 307K credit applications with 122 features using Python. Identified key default predictors through correlation analysis and stratified segmentation. Built three-tier risk model projecting 20-25% default reduction with regulatory-compliant explainable features for fair lending.",
      image: mock01,
      link: "#"
    },
    {
      title: "Geospatial E-Commerce Analytics: US State-Level Analysis",
      description: "Analyzed $1.85M e-commerce revenue across 52 US states using SQL and Tableau. Built interactive geospatial dashboard revealing 2.5× conversion efficiency spread. Statistical analysis identified engagement patterns driving performance gaps, projecting 12-18% revenue lift through data-driven budget reallocation.",
      image: mock02,
      link: "#"
    },
    {
      title: "Production ML Regression: Housing Price Prediction",
      description: "Production-grade gradient boosting model predicting housing prices with R²=0.99 across 1,460 properties. Engineered 89 features with 5-fold cross-validation. Outperformed RandomForest by 16.8%. Enables automated appraisal workflows and portfolio optimization for institutional investors.",
      image: mock03,
      link: "#"
    }
  ];

  return (
    <div className="projects-container" id="projects">
      <motion.h1
        initial={{ opacity: 0, y: 20 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true, margin: "-50px" }}
        transition={{ duration: 0.5 }}
      >
        Projects
      </motion.h1>
      <div className="projects-grid">
        {projects.map((project, index) => (
          <ProjectCard
            key={index}
            title={project.title}
            description={project.description}
            image={project.image}
            link={project.link}
            index={index}
          />
        ))}
      </div>
    </div>
  );
}

export default Project;
